import android.util.Base64
import java.util.regex.Pattern
import android.graphics.Bitmap
import android.graphics.Canvas
import android.graphics.drawable.BitmapDrawable
import java.io.ByteArrayOutputStream


class WireguardNativeBridgeModule(private val reactContext: ReactApplicationContext) :
  ReactContextBaseJavaModule(reactContext) {

    private lateinit var backend: Backend
    private val tunnelName = "wg0"
    private var tunnel: Tunnel? = null
    private var config: Config? = null
    private var connectivityManager: ConnectivityManager? = null



 init {
        try {
           backend = GoBackend(reactApplicationContext)


            connectivityManager = reactContext.getSystemService(Context.CONNECTIVITY_SERVICE) as ConnectivityManager

            if (!android.net.VpnService.prepare(reactContext).equals(null)) {
                Log.w(NAME, "VPN permission not yet granted")
            }
        } catch (e: Exception) {
            Log.e(NAME, "Failed to initialize WireGuard backend", e)
        }
    }

    override fun getName(): String = NAME

      @ReactMethod
      fun prepareVPN(promise: Promise) {
          val vpnIntent = android.net.VpnService.prepare(reactContext)
          if (vpnIntent != null) {
              val currentActivity = currentActivity
              if (currentActivity != null) {
                  currentActivity.startActivityForResult(vpnIntent, VPN_REQUEST_CODE)
                  promise.resolve("VPN permission requested")
              } else {
                  promise.reject("ERROR_NO_ACTIVITY", "No activity available to request VPN permission")
              }
          } else {
              promise.resolve("VPN permission already granted")
          }
      }

      @ReactMethod
      fun startTunnel(configString: String, promise: Promise) {
          try {
              Log.d(NAME, "Parsing WireGuard config...")
              val reader = java.io.BufferedReader(StringReader(configString))
              this.config = Config.parse(reader)
              Log.d(NAME, "Config parsed successfully")

              this.tunnel = object : Tunnel {
                  override fun getName(): String = tunnelName
                  override fun onStateChange(newState: Tunnel.State) {
                      Log.d(NAME, "Tunnel state changed to: $newState")
                  }
              }

              backend.setState(tunnel, Tunnel.State.UP, config)
              Log.d(NAME, "Tunnel started successfully")
              promise.resolve("Tunnel started successfully")
          } catch (e: BackendException) {
              Log.e(NAME, "Backend exception", e)
              promise.reject("ERROR_STARTING_TUNNEL", "Backend error: ${e.message}", e)
          } catch (e: Exception) {
              Log.e(NAME, "General exception", e)
              promise.reject("ERROR_STARTING_TUNNEL", e.message, e)
          }
      }

    @ReactMethod
    fun stopTunnel(promise: Promise) {
        try {
            if (tunnel != null && config != null) {
                backend.setState(tunnel!!, Tunnel.State.DOWN, config!!)
                promise.resolve(null)
            } else {
                promise.reject("DISCONNECT_ERROR", "Tunnel not initialized")
            }
        } catch (e: Exception) {
            promise.reject("DISCONNECT_ERROR", "Failed to disconnect: ${e.message}")
        }
    }

    @ReactMethod
    fun getTunnelStatus(promise: Promise) {
        try {
            this.tunnel = object : Tunnel {
                override fun getName(): String = tunnelName
                override fun onStateChange(newState: Tunnel.State) {}
            }

            val state = backend.getState(tunnel)
            promise.resolve(state.name)
        } catch (e: BackendException) {
            promise.reject("ERROR_GETTING_TUNNEL_STATUS", "Backend error: ${e.message}", e)
        } catch (e: Exception) {
            promise.reject("ERROR_GETTING_TUNNEL_STATUS", e.message, e)
        }
    }

    // kill switch

    @ReactMethod
    fun openVPNSettings(promise: Promise) {
        try {
            val intent = Intent(android.provider.Settings.ACTION_VPN_SETTINGS)
            intent.flags = Intent.FLAG_ACTIVITY_NEW_TASK
            reactContext.startActivity(intent)
            promise.resolve("Opened VPN settings")
        } catch (e: Exception) {
            Log.e(NAME, "Failed to open VPN settings", e)
            promise.reject("ERROR_OPENING_SETTINGS", "Failed to open VPN settings: ${e.message}")
        }
    }

    // New method: Get installed apps for user to select
    @ReactMethod
    fun getInstalledApps(promise: Promise) {
        try {
            val pm = reactContext.packageManager
            val packages = pm.getInstalledApplications(PackageManager.GET_META_DATA)
            val appsList = Arguments.createArray()

            for (packageInfo in packages) {
                // Skip system apps if they don't have a launcher
                if ((packageInfo.flags and ApplicationInfo.FLAG_SYSTEM) != 0) {
                    val intent = pm.getLaunchIntentForPackage(packageInfo.packageName)
                    if (intent == null) {
                        continue
                    }
                }

                val appInfo = Arguments.createMap()
                appInfo.putString("packageName", packageInfo.packageName)
                appInfo.putString("appName", pm.getApplicationLabel(packageInfo).toString())
                appInfo.putInt("uid", packageInfo.uid)

                // Add app icon as Base64 encoded string
                try {
                    val icon = pm.getApplicationIcon(packageInfo.packageName)
                    val bitmap = if (icon is BitmapDrawable) {
                        icon.bitmap
                    } else {
                        // Convert drawable to bitmap if it's not already a bitmap
                        val bmp = Bitmap.createBitmap(icon.intrinsicWidth, icon.intrinsicHeight, Bitmap.Config.ARGB_8888)
                        val canvas = Canvas(bmp)
                        icon.setBounds(0, 0, canvas.width, canvas.height)
                        icon.draw(canvas)
                        bmp
                    }

                    // Compress and convert to Base64
                    val byteArrayOutputStream = ByteArrayOutputStream()
                    bitmap.compress(Bitmap.CompressFormat.PNG, 100, byteArrayOutputStream)
                    val byteArray = byteArrayOutputStream.toByteArray()
                    val base64Icon = Base64.encodeToString(byteArray, Base64.NO_WRAP)

                    appInfo.putString("icon", base64Icon)
                } catch (e: Exception) {
                    Log.e(NAME, "Failed to get icon for ${packageInfo.packageName}", e)
                    appInfo.putString("icon", "")
                }

                appsList.pushMap(appInfo)
            }

            promise.resolve(appsList)
        } catch (e: Exception) {
            Log.e(NAME, "Failed to get installed apps", e)
            promise.reject("GET_APPS_ERROR", e.message, e)
        }
    }

    // Modified startTunnel method with split tunneling support
@ReactMethod
fun startTunnelWithSplitTunnel(configString: String, includedApps: String, excludedApps: String, promise: Promise) {
    try {
        Log.d(NAME, "Parsing config string...")
        val reader = BufferedReader(StringReader(configString))
        val parsedConfig = Config.parse(reader)

        Log.d(NAME, "Rebuilding config manually to apply split tunnel settings...")

        val parsedInterface = parsedConfig.`interface`
        val parsedPeers = parsedConfig.peers

        val ifaceBuilder = Interface.Builder()

        // Handle addresses
        parsedInterface.addresses.forEach { address ->
            ifaceBuilder.addAddress(address)
        }

        // Handle DNS servers
        parsedInterface.dnsServers.forEach { server ->
            ifaceBuilder.addDnsServer(server)
        }

     // Extract private key directly from the original config string
        val privateKeyPattern = Pattern.compile("PrivateKey\\s*=\\s*([^\\s]+)")
        val matcher = privateKeyPattern.matcher(configString)
        if (matcher.find()) {
            val privateKeyValue = matcher.group(1).trim()
            ifaceBuilder.parsePrivateKey(privateKeyValue)
        } else {
            throw Exception("Could not find PrivateKey in config")
        }


        // Add included applications if provided
        if (includedApps.isNotEmpty()) {
            Log.d(NAME, "Setting included applications: $includedApps")
            ifaceBuilder.parseIncludedApplications(includedApps)
        }

        // Add excluded applications if provided
        if (excludedApps.isNotEmpty()) {
            Log.d(NAME, "Setting excluded applications: $excludedApps")
            ifaceBuilder.parseExcludedApplications(excludedApps)
        }

        // Handle optional MTU
        parsedInterface.mtu.ifPresent { ifaceBuilder.setMtu(it) }

        // Handle optional ListenPort
        parsedInterface.listenPort.ifPresent { ifaceBuilder.setListenPort(it) }

        val configBuilder = Config.Builder()
            .setInterface(ifaceBuilder.build())

        for (peer in parsedPeers) {
            val peerBuilder = Peer.Builder()

            // Allowed IPs
            peer.allowedIps.forEach { ip ->
                peerBuilder.addAllowedIp(ip)
            }

            // Public key
            peer.publicKey?.let {
                peerBuilder.parsePublicKey(it.toBase64())
            }

            // Endpoint
            peer.endpoint.ifPresent {
                peerBuilder.setEndpoint(it)
            }

            // Keepalive
            peer.persistentKeepalive.ifPresent {
                peerBuilder.setPersistentKeepalive(it)
            }

            configBuilder.addPeer(peerBuilder.build())
        }

        this.config = configBuilder.build()

        this.tunnel = object : Tunnel {
            override fun getName(): String = tunnelName
            override fun onStateChange(newState: Tunnel.State) {
                Log.d(NAME, "Tunnel state changed to: $newState")
            }
        }

        backend.setState(tunnel, Tunnel.State.UP, config)
        Log.d(NAME, "Tunnel started successfully with modified config")
        promise.resolve("Tunnel started successfully")
    } catch (e: BackendException) {
        Log.e(NAME, "Backend exception", e)
        promise.reject("ERROR_STARTING_TUNNEL", "Backend error: ${e.message}", e)
    } catch (e: Exception) {
        Log.e(NAME, "General exception", e)
        promise.reject("ERROR_STARTING_TUNNEL", e.message, e)
    }
}

  companion object {
    const val NAME = "WireguardNativeBridge"
    const val VPN_REQUEST_CODE = 24601
  }
}
